namespace sv_f7e3ec3fb05c462ba5797cf765a1231d.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_f7e3ec3fb05c462ba5797cf765a1231d.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => HandleStepClick(stepIndex)" role="button" tabindex="@(status == "completed" ? 0 : -1)">
                <span class="step-marker">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task HandleStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@namespace sv_f7e3ec3fb05c462ba5797cf765a1231d.Components.Pages.Apply

<div class="step-panel">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" class="form-control" />
        @if (!string.IsNullOrEmpty(_emailError))
        {
            <span class="field-error">@_emailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" @bind="Address" @bind:event="oninput" class="form-control" />
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@_isValidating">
            @if (_isValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";

    [Parameter] public EventCallback<PersonalInfoResult> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? _validationError;
    private string? _emailError;
    private bool _isValidating;

    private async Task HandleNext()
    {
        _validationError = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            _validationError = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            _isValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            _isValidating = false;

            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfoResult(FullName, Email, Phone, Address));
    }

    public record PersonalInfoResult(string FullName, string Email, string Phone, string Address);
}

@namespace sv_f7e3ec3fb05c462ba5797cf765a1231d.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Entry.Company" @oninput="e => Update(Entry with { Company = e.Value?.ToString() ?? "" })" class="form-control" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title" @oninput="e => Update(Entry with { Title = e.Value?.ToString() ?? "" })" class="form-control" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => Update(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" class="form-control" />
        </div>
        <div class="form-group">
            <label class="checkbox-label">
                <input type="checkbox" checked="@_isCurrent" @onchange="HandleCurrentToggle" />
                Currently working here
            </label>
            @if (!_isCurrent)
            {
                <label>End Date</label>
                <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")" @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!) })" class="form-control" />
            }
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @oninput="e => Update(Entry with { Description = e.Value?.ToString() ?? "" })" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool _isCurrent => Entry.EndDate is null && Entry.IsCurrent;

    private void Update(WorkEntryModel updated)
    {
        OnChanged.InvokeAsync(updated);
    }

    private void HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        OnChanged.InvokeAsync(updated);
    }

    public record WorkEntryModel(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description, bool IsCurrent);
}

@namespace sv_f7e3ec3fb05c462ba5797cf765a1231d.Components.Pages.Apply

<div class="step-panel">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="@index"
                       CanRemove="@(Entries.Count > 1)"
                       OnChanged="@(updated => HandleEntryChanged(index, updated))"
                       OnRemove="@(() => HandleRemove(index))" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryForm.WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryForm.WorkEntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void HandleEntryChanged(int index, WorkEntryForm.WorkEntryModel updated)
    {
        Entries[index] = updated;
    }

    private void HandleRemove(int index)
    {
        Entries.RemoveAt(index);
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryForm.WorkEntryModel("", "", DateTime.Today, null, "", false));
    }

    private async Task HandleNext()
    {
        _validationError = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _validationError = "Each position requires at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}

@namespace sv_f7e3ec3fb05c462ba5797cf765a1231d.Components.Pages.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" value="@Entry.Name" @oninput="e => Update(Entry with { Name = e.Value?.ToString() ?? "" })" class="form-control" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" value="@Entry.Relationship" @oninput="e => Update(Entry with { Relationship = e.Value?.ToString() ?? "" })" class="form-control" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email" @oninput="e => Update(Entry with { Email = e.Value?.ToString() ?? "" })" class="form-control" />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" value="@Entry.Phone" @oninput="e => Update(Entry with { Phone = e.Value?.ToString() ?? "" })" class="form-control" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void Update(ReferenceModel updated)
    {
        OnChanged.InvokeAsync(updated);
    }

    public record ReferenceModel(string Name, string Relationship, string Email, string Phone);
}

@namespace sv_f7e3ec3fb05c462ba5797cf765a1231d.Components.Pages.Apply

<div class="step-panel">
    <h2>References</h2>
    <p class="step-description">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@References[index]"
                       Index="@index"
                       CanRemove="@(References.Count > 2)"
                       OnChanged="@(updated => HandleChanged(index, updated))"
                       OnRemove="@(() => HandleRemove(index))" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceForm.ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void HandleChanged(int index, ReferenceForm.ReferenceModel updated)
    {
        References[index] = updated;
    }

    private void HandleRemove(int index)
    {
        References.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceForm.ReferenceModel("", "", "", ""));
        }
    }

    private async Task HandleNext()
    {
        _validationError = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _validationError = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }
}

@namespace sv_f7e3ec3fb05c462ba5797cf765a1231d.Components.Pages.Apply

<div class="step-panel">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <textarea class="form-control cover-letter-textarea"
                  rows="12"
                  maxlength="2000"
                  value="@CoverLetter"
                  @oninput="HandleInput"
                  placeholder="Write your cover letter here..."></textarea>
        <div class="character-count @(CoverLetter.Length > 1800 ? "warning" : "")">
            @CoverLetter.Length / 2000 characters
        </div>
    </div>

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private void HandleInput(ChangeEventArgs e)
    {
        CoverLetter = e.Value?.ToString() ?? "";
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_f7e3ec3fb05c462ba5797cf765a1231d.Components.Pages.Apply

<div class="step-panel">
    <h2>Review & Submit</h2>

    @if (_submitted)
    {
        <div class="submission-confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@_applicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-section-header">
                <h3>Personal Information</h3>
                <button class="btn-link" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
            </div>
            <dl class="review-data">
                <dt>Full Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Work History</h3>
                <button class="btn-link" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <div class="review-dates">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </div>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="review-description">@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>References</h3>
                <button class="btn-link" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)<br />
                    @r.Email | @r.Phone
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h3>Cover Letter</h3>
                <button class="btn-link" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(_error))
        {
            <div class="validation-summary">@_error</div>
        }

        <div class="step-buttons">
            <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@_isSubmitting">
                @if (_isSubmitting)
                {
                    <span>Submitting...</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkEntryForm.WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEdit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string? _error;

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        _isSubmitting = true;
        _error = null;
        StateHasChanged();

        try
        {
            _applicationId = await OnSubmit();
            _submitted = true;
        }
        catch (Exception ex)
        {
            _error = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

